// src/parsers/curriculum.ts
function parseCurriculumDashboard(html) {
  const doc = parseHTMLFast(html);
  let totalCredits = "0";
  const allElements = doc.body.getElementsByTagName("*");
  for (let i = 0;i < allElements.length; i++) {
    const text = allElements[i].textContent || "";
    if (text.includes("Total Credits")) {
      const match = text.match(/Total Credits\s*[:=-]?\s*([\d.]+)/i);
      if (match) {
        totalCredits = match[1];
        break;
      }
    }
  }
  const categories = [];
  const clickables = doc.querySelectorAll("[onclick]");
  clickables.forEach((el) => {
    const onclick = el.getAttribute("onclick") || "";
    const idMatch = onclick.match(/['"]([A-Z]{2,4})['"]/);
    if (idMatch) {
      const id = idMatch[1];
      if (categories.find((c) => c.id === id))
        return;
      let title = id;
      const titleEl = el.querySelector(".col-6 span") || el.querySelector(".text-left");
      if (titleEl && titleEl.textContent) {
        title = titleEl.textContent.trim();
      } else {
        const raw = el.textContent || "";
        const clean = raw.replace(/Credit:\s*[\d.]+/gi, "").replace(/Max\.\s*Credit:\s*[\d.]+/gi, "").replace(id, "");
        title = clean.replace(/\s+/g, " ").trim();
      }
      title = title.replace(/^[-:]+/, "").trim();
      const textContent = el.textContent || "";
      const creditMatch = textContent.match(/([\d.]+)\s*\/\s*([\d.]+)/);
      let credits = "0";
      let maxCredits = "0";
      if (creditMatch) {
        credits = creditMatch[1];
        maxCredits = creditMatch[2];
      } else {
        const numbers = textContent.match(/[\d.]+/g);
        if (numbers && numbers.length >= 2) {
          credits = numbers[0];
          maxCredits = numbers[1];
        }
      }
      categories.push({
        id,
        title: title || id,
        credits,
        maxCredits,
        isCompleted: parseFloat(credits) >= parseFloat(maxCredits)
      });
    }
  });
  return { totalCredits, categories };
}
function parseCurriculumCategoryTable(html) {
  const doc = parseHTMLFast(html);
  const basketMap = {};
  const basketMaxCredits = {};
  const navButtons = doc.querySelectorAll(".nav-tabs button");
  navButtons.forEach((btn) => {
    const target = btn.getAttribute("data-bs-target") || "";
    const name = btn.textContent?.trim() || "";
    if (target && name) {
      basketMap[target.replace("#", "")] = name;
    }
  });
  const tabPanes = doc.querySelectorAll(".tab-pane");
  tabPanes.forEach((pane) => {
    if (pane.id && basketMap[pane.id]) {
      const basket = basketMap[pane.id];
      const text = pane.textContent || "";
      const match = text.match(/Maximum Basket Credits Allowed\s*:\s*([\d.]+)/i);
      if (match) {
        basketMaxCredits[basket] = match[1];
      }
    }
  });
  const rows = doc.querySelectorAll("table tbody tr");
  const courses = [];
  rows.forEach((row) => {
    const cells = row.querySelectorAll("td");
    if (cells.length < 5)
      return;
    let codeIndex = -1;
    for (let i = 0;i < cells.length; i++) {
      if (/^[A-Z]{3,4}\d{3}[A-Z0-9]*$/.test(cells[i].innerText.trim())) {
        codeIndex = i;
        break;
      }
    }
    let basket = "Core";
    let currentPane = row.closest(".tab-pane");
    while (currentPane) {
      if (currentPane.id && basketMap[currentPane.id]) {
        basket = basketMap[currentPane.id];
        break;
      }
      currentPane = currentPane.parentElement?.closest(".tab-pane") || null;
    }
    if (basket === "Core") {
      if (navButtons.length === 1) {
        basket = navButtons[0].textContent?.trim() || "Core";
      } else if (navButtons.length > 1) {
        basket = navButtons[0].textContent?.trim() || "Core";
      }
    }
    if (codeIndex !== -1) {
      courses.push({
        sl: cells[0]?.textContent?.trim() || "",
        code: cells[codeIndex]?.textContent?.trim() || "",
        title: cells[codeIndex + 1]?.textContent?.trim() || "",
        type: cells[codeIndex + 2]?.textContent?.trim() || "TH",
        credits: cells[codeIndex + 3]?.textContent?.trim() || "0",
        l: cells[codeIndex + 4]?.textContent?.trim() || "0",
        t: cells[codeIndex + 5]?.textContent?.trim() || "0",
        p: cells[codeIndex + 6]?.textContent?.trim() || "0",
        j: cells[codeIndex + 7]?.textContent?.trim() || "0",
        basket,
        isCompleted: row.getAttribute("style")?.toLowerCase().includes("background") || row.className.toLowerCase().includes("success") || Array.from(cells).some((c) => c.textContent?.toLowerCase().includes("completed"))
      });
    }
  });
  return { courses, basketMaxCredits };
}

// src/parsers/grades.ts
function parseGradesSemesters(html) {
  const doc = parseHTMLFast(html);
  const select = doc.getElementById("semesterSubId");
  if (!select)
    return [];
  const semesters = [];
  const options = select.querySelectorAll("option");
  options.forEach((opt) => {
    const val = opt.value;
    if (val) {
      semesters.push({ id: val, label: opt.textContent?.trim() || "", isLatest: false });
    }
  });
  if (semesters.length > 0) {
    semesters[0].isLatest = true;
  }
  return semesters;
}
function parseGrades(html) {
  const doc = parseHTMLFast(html);
  const courses = [];
  let gpa = "";
  const gpaSpan = doc.evaluate("//span[contains(text(), 'GPA :')]", doc, null, XPathResult.FIRST_ORDERED_NODE_TYPE, null).singleNodeValue;
  if (gpaSpan && gpaSpan.textContent) {
    gpa = gpaSpan.textContent.replace("GPA :", "").trim();
  }
  const rows = doc.querySelectorAll("table.table-hover tr");
  rows.forEach((row) => {
    if (row.getAttribute("style")?.includes("background-color: #3c8dbc"))
      return;
    if (row.querySelector("th"))
      return;
    const cells = row.querySelectorAll("td");
    if (cells.length < 12)
      return;
    if (cells[0].textContent?.trim().match(/^\d+$/)) {
      const code = cells[1].textContent?.trim() || "";
      const title = cells[2].textContent?.trim() || "";
      const type = cells[3].textContent?.trim() || "";
      const l = cells[4].textContent?.trim() || "";
      const p = cells[5].textContent?.trim() || "";
      const j = cells[6].textContent?.trim() || "";
      const c = cells[7].textContent?.trim() || "";
      const gradingType = cells[8].textContent?.trim() || "";
      const grandTotal = cells[9].textContent?.trim() || "";
      const grade = cells[10].textContent?.trim() || "";
      let courseId = "";
      const btn = cells[11].querySelector("button");
      if (btn) {
        const onclick = btn.getAttribute("onclick") || "";
        const match = onclick.match(/'(.*?)'/);
        if (match) {
          courseId = match[1];
        }
      }
      const notIncludedInGpa = row.getAttribute("style")?.includes("#C0D8C0") || false;
      courses.push({
        code,
        title,
        type,
        credits: "",
        l,
        p,
        j,
        c,
        gradingType,
        grandTotal,
        grade,
        courseId,
        notIncludedInGpa
      });
    }
  });
  return { gpa, courses };
}
function parseGradeDetails(html) {
  const doc = parseHTMLFast(html);
  const result = {};
  const innerTables = doc.querySelectorAll("table.table-striped");
  if (innerTables.length >= 2) {
    const statsTable = innerTables[0];
    const statsRows = statsTable.querySelectorAll("tr");
    if (statsRows.length >= 3) {
      const dataCells = statsRows[2].querySelectorAll("td");
      if (dataCells.length >= 11) {
        result.classStrength = dataCells[0]?.textContent?.trim() || "";
        result.gradingStrength = dataCells[1]?.textContent?.trim() || "";
        result.mean = dataCells[2]?.textContent?.trim() || "";
        result.sd = dataCells[3]?.textContent?.trim() || "";
        result.gradesRange = {
          S: dataCells[4]?.textContent?.trim() || "",
          A: dataCells[5]?.textContent?.trim() || "",
          B: dataCells[6]?.textContent?.trim() || "",
          C: dataCells[7]?.textContent?.trim() || "",
          D: dataCells[8]?.textContent?.trim() || "",
          E: dataCells[9]?.textContent?.trim() || "",
          F: dataCells[10]?.textContent?.trim() || ""
        };
      }
    }
    const assTable = innerTables[1];
    const assRows = assTable.querySelectorAll("tbody tr");
    const assessments = [];
    assRows.forEach((row) => {
      const cells = row.querySelectorAll("td");
      if (cells.length >= 7) {
        assessments.push({
          title: cells[1]?.textContent?.trim() || "",
          maxMark: cells[2]?.textContent?.trim() || "",
          weightage: cells[3]?.textContent?.trim() || "",
          status: cells[4]?.textContent?.trim() || "",
          scoredMark: cells[5]?.textContent?.trim() || "",
          weightageMark: cells[6]?.textContent?.trim() || ""
        });
      }
    });
    result.assessments = assessments;
  }
  return result;
}
